// Original game bookings. These are simulation activities, not a provider's real booking menu.
export function serviceMenu(store){
 const n=store.name;
 if(store.businessKind==='visitor')return [{id:'orientation',name:'Plan a mall route',price:0,minutes:5,recovery:3,animation:'rest',description:'Choose your next stop with the team and collect a visit stamp.'},{id:'package-help',name:'Package check & shopping break',price:0,minutes:10,recovery:12,animation:'rest',description:'Put your purchases down and take a quiet break.'}];
 if(store.businessKind==='auto')return [{id:'design',name:'Explore the showroom',price:0,minutes:15,recovery:4,animation:'demo',description:'View the showroom and compare an original game color display.'},{id:'showroom',name:'Seated showroom consultation',price:0,minutes:20,recovery:10,animation:'rest',description:'A game visit; no real vehicle purchase, finance or booking.'}];
 if(store.businessKind==='gallery')return [{id:'view',name:'Gallery viewing',price:0,minutes:15,recovery:8,animation:'artwalk',description:'Slow down for an original illustrated art viewing.'},{id:'session',name:'Creative studio session',price:1500,minutes:25,recovery:12,animation:'artwalk',description:'An original game art session, with a journal stamp.'}];
 if(store.businessKind==='entertainment')return [{id:'ticket',name:/AMC|Regal|cinema|THE LOT/i.test(n)?'Movie ticket':'Play session',price:1800,minutes:40,recovery:22,animation:/AMC|Regal|cinema|THE LOT/i.test(n)?'cinema':'carousel',description:'A simulated attraction visit. Unused tickets can be refunded at this branch.'},{id:'short',name:'Short visit',price:800,minutes:15,recovery:10,animation:'rest',description:'A quick game break between shopping stops.'}];
 if(/repair|fix|shoe lab/i.test(n))return [{id:'repair',name:'Care & repair appointment',price:1500,minutes:20,recovery:7,animation:'demo',description:'Inspect a purchase and take part in a simulated care appointment.'},{id:'consult',name:'Care consultation',price:0,minutes:10,recovery:5,animation:'rest',description:'A short simulated service visit with the team.'}];
 if(/photo|portraits/i.test(n))return [{id:'photo',name:'Portrait session',price:1000,minutes:15,recovery:8,animation:'photo',description:'A game portrait session and a saved visit stamp.'},{id:'consult',name:'Plan a portrait',price:0,minutes:5,recovery:3,animation:'rest',description:'Meet the team and plan your next outfit photograph.'}];
 if(/fitness|yoga|barry|training|equinox|life time|crunch|swim/i.test(n))return [{id:'daypass',name:'Wellness day pass',price:2000,minutes:30,recovery:25,animation:'rest',description:'An original game wellness break. Recovery values are game mechanics.'},{id:'tour',name:'Meet the team',price:0,minutes:10,recovery:7,animation:'rest',description:'A short game tour and visit stamp.'}];
 return [{id:'appointment',name:/nail/i.test(n)?'Manicure session':/barber|salon|drybar|hair/i.test(n)?'Styling session':'Self-care session',price:2500,minutes:25,recovery:18,animation:'rest',description:'A simulated appointment, not a real provider menu or health recommendation.'},{id:'consult',name:'Meet the team',price:0,minutes:10,recovery:6,animation:'rest',description:'A complimentary game consultation and visit stamp.'}];
}
